#[cfg(test)]pub(crate) mod finite_history_development_tests {
 use super::*;
 pub(crate) fn history_for(generation:u64,seq:u64)->History {
  let catalog=SpriteActionCatalog::parse_for_inspection(&[b"11297 0 0\n".as_slice(),include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-resurrection61-inspection\20261024-122925-908479\230.definition.txt")].concat(),super::super::sprite_actions::ActionLimits::default()).unwrap();let clip=Clip::new(Arc::new(catalog.resolve_action(230,ActionKey::new(0)).unwrap().animation.clone())).unwrap();let mut playback=clip.start();playback.advance(0).unwrap();
  History{generation:Some(generation),seen:BTreeSet::from([seq]),active:vec![Active{cue:Effect{sequence:seq,graphics:230,target:None,position:[100,100]},heading:0,start:0,playback}],started:1,omitted:0}
 }
 pub(crate) fn has_seen(history:&History,seq:u64)->bool{history.seen.contains(&seq)}
 fn world(seq:u64)->World {let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();w.generation=7;w.effects=vec![Effect{sequence:seq,graphics:230,target:None,position:[100,100]}];w}
 fn view()->ViewProjection{ViewProjection{anchor_cell:WorldCell{x:100,y:100},anchor_pixel:super::super::world_map::PixelPoint{x:0,y:0}}}
 #[test]fn source_retirement_clears_cursor_but_keeps_admission_and_counters(){let mut e=Effects::default();e.restore_history_with_source(history_for(7,41),false);assert!(e.active.is_empty());assert_eq!(e.started,1);assert!(e.seen.contains(&41));let w=world(41);let mut canvas=Canvas::new(1,1).unwrap();let(_,events)=e.draw_to(&w,&mut super::super::native_world_effects::Target::Canvas(&mut canvas),view(),1_000_000);assert!(events.is_empty());assert_eq!((e.started,e.omitted,e.active.len()),(1,0,0));}
 #[test]fn same_source_restores_cursor_after_initial_audio_instead_of_reentering_it(){let h=history_for(7,41);let mut e=Effects::default();e.restore_history_with_source(h.clone(),true);let s=e.active[0].playback.advance(83_000_000).unwrap();assert_eq!(s.source_frame,2);assert!(s.crossed_cues.is_empty());assert_eq!(e.history().active_sequences(),BTreeSet::from([41]));assert_eq!(h.active[0].playback.sampled_native_millis(),Some(0));}
 #[test]fn late_worker_merges_only_same_generation_admission_not_old_cursor_or_audio(){let mut base=history_for(7,41);base.merge_admission(&history_for(7,42));assert!(base.seen.contains(&42));assert_eq!(base.active_sequences(),BTreeSet::from([41]));base.merge_admission(&history_for(8,43));assert!(!base.seen.contains(&43));assert_eq!(base.started,1);}
 #[test]fn failed_reprepare_retires_active_once_and_releases_audio_sequence(){let mut e=Effects::default();e.restore_history_with_source(history_for(7,41),true);let w=world(41);let mut canvas=Canvas::new(1,1).unwrap();e.draw_to(&w,&mut super::super::native_world_effects::Target::Canvas(&mut canvas),view(),1_000_000);assert!(e.history().active_sequences().is_empty());assert_eq!(e.omitted,1);e.draw_to(&w,&mut super::super::native_world_effects::Target::Canvas(&mut canvas),view(),2_000_000);assert_eq!((e.started,e.omitted),(1,1));}
 #[test]fn generation_change_retires_old_admission_even_when_sequence_value_is_reused(){let mut e=Effects::default();e.restore_history_with_source(history_for(7,41),false);let mut w=world(41);w.generation=8;let mut canvas=Canvas::new(1,1).unwrap();e.draw_to(&w,&mut super::super::native_world_effects::Target::Canvas(&mut canvas),view(),1_000_000);assert_eq!(e.generation,Some(8));assert_eq!((e.started,e.omitted),(0,1));assert!(e.seen.contains(&41));}
 #[test]
 #[ignore="LITO_SHARED_RESOURCE_ROOT; original230/124, raw eviction and source retirement; memory fragments only"]
 fn real_bank_history_survives_raw_eviction_without_replaying_source_one_audio(){let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=world(41);let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.additional_error.is_none());let mut q=vec![];let(_,audio)=e.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut q),view(),0);assert_eq!(audio.iter().filter(|e|e.sound==Some(124)&&e.prepared_audio.is_some()).count(),1);assert_eq!(q.len(),1);drop(q);let h=e.history();w.effects.clear();let mut same=Effects::default();same.restore_history_with_source(h.clone(),true);same.prepare(&root,&w,&cancel);let mut q=vec![];let(_,audio)=same.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut q),view(),83_000_000);assert!(audio.is_empty());assert_eq!(q.len(),1);drop(q);assert_eq!(same.history().active_sequences(),BTreeSet::from([41]));let mut retired=Effects::default();retired.restore_history_with_source(h,false);w.effects=world(41).effects;retired.prepare(&root,&w,&cancel);let mut q=vec![];let(_,audio)=retired.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut q),view(),83_000_000);assert!(audio.is_empty()&&q.is_empty());drop(q);assert_eq!(retired.started,1);}
}
